// Station 2.4: Bot-Alarm! Wie schnell ist das Verzeichnis wirklich?

World welt = new World(800, 480);

// Aufgabe 3: Höhe des Verzeichnisses (TODO 3)
Binaerbaum verzeichnis = new Binaerbaum();
verzeichnis.einfuegenAlle("Mika Emil Tara Bo Ines Pia Zoe Dana Kai Ruby Vik");
println("Verzeichnis: " + verzeichnis.anzahl() + " Accounts, Höhe " + verzeichnis.hoehe());

// Aufgabe 4: Die Bot-Welle. 500 Bots registrieren sich in alphabetischer Reihenfolge.
String[] bots = new String[500];
for (int i = 0; i < bots.length; i++) {
   String nummer = "" + (i + 1);
   while (nummer.length() < 3) {
      nummer = "0" + nummer;
   }
   bots[i] = "Bot" + nummer;          // Bot001, Bot002, …, Bot500
}
Binaerbaum botBaum = new Binaerbaum();
for (int i = 0; i < bots.length; i++) {
   botBaum.einfuegen(new Spieler(bots[i], 1));
}
println("Bot-Welle: " + botBaum.anzahl() + " Accounts, Höhe " + botBaum.hoehe());
Spieler.vergleiche = 0;
botBaum.suchen(new Spieler("Bot500"));
println("  Login von Bot500: " + Spieler.vergleiche + " Vergleiche");

// Aufgabe 5: dieselben Bots in zufälliger Reihenfolge
String[] gemischt = new String[bots.length];
for (int i = 0; i < bots.length; i++) {
   gemischt[i] = bots[i];
}
Random zufall = new Random();
for (int i = gemischt.length - 1; i > 0; i--) {
   int j = zufall.nextInt(i + 1);
   String tausch = gemischt[i];
   gemischt[i] = gemischt[j];
   gemischt[j] = tausch;
}
Binaerbaum zufallsBaum = new Binaerbaum();
for (int i = 0; i < gemischt.length; i++) {
   zufallsBaum.einfuegen(new Spieler(gemischt[i], 1));
}
println("Zufällig: " + zufallsBaum.anzahl() + " Accounts, Höhe " + zufallsBaum.hoehe());
Spieler.vergleiche = 0;
zufallsBaum.suchen(new Spieler("Bot500"));
println("  Login von Bot500: " + Spieler.vergleiche + " Vergleiche");

// Aufgabe 6 (Selbst bauen): ausgewogen einfügen, immer zuerst die Mitte (TODO 6)
Binaerbaum ausgewogen = new Binaerbaum();
ausgewogen.ausgewogenEinfuegen(bots, 0, bots.length - 1);
println("Ausgewogen: " + ausgewogen.anzahl() + " Accounts, Höhe " + ausgewogen.hoehe());
Spieler.vergleiche = 0;
ausgewogen.suchen(new Spieler("Bot500"));
println("  Login von Bot500: " + Spieler.vergleiche + " Vergleiche");

new BaumZeichner().zeichne(verzeichnis);   // auch: botBaum, zufallsBaum, ausgewogen

/**
 * Das Spielerverzeichnis als geordneter Binärbaum. wurzel ist nie null:
 * Im leeren Baum ist die Wurzel ein Abschluss.
 */
public class Binaerbaum {
   private BaumElement wurzel;

   public Binaerbaum() {
      wurzel = new Abschluss();
   }

   public BaumElement getWurzel() {
      return wurzel;
   }

   // Rückgabe false, wenn der Name schon vergeben ist
   public boolean einfuegen(DatenElement d) {
      if (suchen(d) != null) {
         return false;
      }
      wurzel = wurzel.einfuegen(d);
      return true;
   }

   public DatenElement suchen(DatenElement d) {
      return wurzel.suchen(d);
   }

   public String inorder() {
      return wurzel.inorder();
   }

   public String preorder() {
      return wurzel.preorder();
   }

   public String postorder() {
      return wurzel.postorder();
   }

   public int anzahl() {
      return wurzel.anzahl();
   }

   public int hoehe() {
      return wurzel.hoehe();
   }

   // Hilfsmethode für Experimente: fügt alle durch Leerzeichen getrennten Namen
   // nacheinander ein (jeweils mit Level 1)
   public void einfuegenAlle(String namen) {
      String[] teile = namen.trim().split(" ");
      for (int i = 0; i < teile.length; i++) {
         if (teile[i].length() > 0) {
            einfuegen(new Spieler(teile[i], 1));
         }
      }
   }

   // Fügt sortiert[von] bis sortiert[bis] so ein, dass der Baum möglichst niedrig wird.
   public void ausgewogenEinfuegen(String[] sortiert, int von, int bis) {
      if (von > bis) {                                  // ① leerer Bereich: fertig
         return;
      }
      int mitte = (von + bis) / 2;
      einfuegen(new Spieler(sortiert[mitte], 1));       // ② die Mitte zuerst
      ausgewogenEinfuegen(sortiert, von, mitte - 1);    // ③ dann die linke Hälfte
      ausgewogenEinfuegen(sortiert, mitte + 1, bis);    // ④ dann die rechte Hälfte
   }
}

/**
 * Gemeinsamer Typ von Knoten und Abschluss (Entwurfsmuster Kompositum).
 */
public abstract class BaumElement {

   // Fügt d ein. Rückgabe: das Element, das danach an dieser Stelle steht.
   public abstract BaumElement einfuegen(DatenElement d);

   // Rückgabe: die gespeicherten Daten mit gleichem Schlüssel oder null.
   public abstract DatenElement suchen(DatenElement d);

   // Alle Namen ab hier, jeder mit einem Leerzeichen dahinter
   public abstract String inorder();      // links – ich – rechts

   public abstract String preorder();     // ich – links – rechts

   public abstract String postorder();    // links – rechts – ich

   // Anzahl der Knoten ab hier
   public abstract int anzahl();

   // Zahl der Ebenen ab hier (Abschluss: 0)
   public abstract int hoehe();
}

/**
 * Ein Knoten des Binärbaums: Daten und zwei Teilbäume. Links stehen die
 * kleineren Schlüssel, rechts die größeren. links und rechts sind nie null:
 * Wo ein Teilbaum leer ist, steht ein Abschluss.
 * Suche (Strg + F) nach "TODO". Die Platzhalter liefern absichtlich falsche Werte.
 * einfuegen und suchen sind die Lösung aus Station 2.2.
 */
public class Knoten extends BaumElement {
   private DatenElement daten;
   private BaumElement links;
   private BaumElement rechts;

   public Knoten(DatenElement daten) {
      this.daten = daten;
      links = new Abschluss();
      rechts = new Abschluss();
   }

   public DatenElement getDaten() {
      return daten;
   }

   public BaumElement getLinks() {
      return links;
   }

   public BaumElement getRechts() {
      return rechts;
   }

   public BaumElement einfuegen(DatenElement d) {
      if (daten.istGleich(d)) {                // ① gleicher Name:
         return this;                          //    nichts ändern
      } else if (daten.istGroesserAls(d)) {    // ② d ist kleiner:
         links = links.einfuegen(d);           //    links einfügen
      } else {                                 // ③ d ist größer:
         rechts = rechts.einfuegen(d);         //    rechts einfügen
      }
      return this;
   }

   public DatenElement suchen(DatenElement d) {
      if (daten.istGleich(d)) {                // ① gefunden:
         return daten;                         //    gespeicherte Daten zurück
      } else if (daten.istGroesserAls(d)) {    // ② d ist kleiner:
         return links.suchen(d);               //    nur links weitersuchen
      } else {                                 // ③ d ist größer:
         return rechts.suchen(d);              //    nur rechts weitersuchen
      }
   }

   public String inorder() {
      return links.inorder() + daten.gibSchluesselwert() + " " + rechts.inorder();
   }

   public String preorder() {
      return daten.gibSchluesselwert() + " " + links.preorder() + rechts.preorder();
   }

   public String postorder() {
      return links.postorder() + rechts.postorder() + daten.gibSchluesselwert() + " ";
   }

   public int anzahl() {
      return links.anzahl() + rechts.anzahl() + 1;
   }

   public int hoehe() {
      return 1 + Math.max(links.hoehe(), rechts.hoehe());
   }
}

/**
 * Der Abschluss steht überall dort, wo ein Teilbaum leer ist, auch im
 * leeren Baum. Er hat weder Daten noch Teilbäume.
 */
public class Abschluss extends BaumElement {

   public BaumElement einfuegen(DatenElement d) {
      return new Knoten(d);                    // ④ hier ist der freie Platz
   }

   public DatenElement suchen(DatenElement d) {
      return null;                             // ④ bis hierher nicht gefunden
   }

   // Ein leerer Teilbaum hat keine Namen.
   public String inorder() {
      return "";
   }

   public String preorder() {
      return "";
   }

   public String postorder() {
      return "";
   }

   public int anzahl() {
      return 0;
   }

   public int hoehe() {
      return 0;
   }
}

/**
 * Der Vertrag für alles, was im Verzeichnis stehen darf (wie in 1.3 und 1.4).
 */
public interface DatenElement {
   String gibSchluesselwert();

   boolean istGleich(DatenElement d);        // gleicher Schlüssel

   boolean istGroesserAls(DatenElement d);   // eigener Schlüssel kommt im Alphabet später
}

/**
 * Ein Account im Online-Spiel Sternenstaub. Der Schlüssel ist der Name.
 */
public class Spieler implements DatenElement {
   private String name;
   private int level;

   // Zählt, wie oft istGleich aufgerufen wird: so viele Knoten hat eine Suche besucht.
   public static int vergleiche = 0;

   public Spieler(String name, int level) {
      this.name = name;
      this.level = level;
   }

   // Zum Suchen: ein Spieler, von dem man nur den Namen kennt
   public Spieler(String name) {
      this.name = name;
      this.level = 0;
   }

   public String getName() {
      return name;
   }

   public int getLevel() {
      return level;
   }

   public String gibSchluesselwert() {
      return name;
   }

   public boolean istGleich(DatenElement d) {
      vergleiche++;
      return name.equals(d.gibSchluesselwert());
   }

   // compareTo vergleicht Texte alphabetisch: Ergebnis > 0, wenn name später kommt
   public boolean istGroesserAls(DatenElement d) {
      return name.compareTo(d.gibSchluesselwert()) > 0;
   }
}

/**
 * Zeichnet einen Binärbaum in die Welt. Fertig, muss nicht verändert werden.
 * Knoten: orange Kreise. Abschlüsse: kleine graue Quadrate.
 * Ab Ebene 6 wird nicht weiter gezeichnet (Pünktchen).
 */
public class BaumZeichner {

   public void zeichne(Binaerbaum baum) {
      zeichneTeilbaum(baum.getWurzel(), 400, 45, 200, 1);
   }

   private void zeichneTeilbaum(BaumElement e, double x, double y, double abstand, int ebene) {
      if (e instanceof Knoten) {
         Knoten k = (Knoten) e;
         if (ebene > 6) {
            Text t = new Text(x - 10, y - 20, 28, "…");
            t.setFillColor(Color.white);
            return;
         }
         zeichneAst(k.getLinks(), x, y, -abstand, ebene);
         zeichneAst(k.getRechts(), x, y, abstand, ebene);
         Circle c = new Circle(x, y, 30);
         c.setFillColor(Color.orange);
         c.setBorderColor(Color.white);
         Text t = new Text(x, y - 11, 20, k.getDaten().gibSchluesselwert());
         t.setAlignment(Alignment.center);
         t.setFillColor(Color.black);
      } else {
         Rectangle q = new Rectangle(x - 7, y - 7, 14, 14);
         q.setFillColor(Color.gray);
         q.setBorderColor(Color.gray);
      }
   }

   // Linie zum Kind; ein Abschluss hängt nur kurz unter dem Knoten
   private void zeichneAst(BaumElement kind, double x, double y, double dx, int ebene) {
      double zx = x + dx;
      double zy = y + 75;
      if (!(kind instanceof Knoten)) {
         zx = x + dx / Math.abs(dx) * Math.min(Math.abs(dx), 28);
         zy = y + 50;
      }
      Line l = new Line(x, y, zx, zy);
      l.setBorderColor(Color.gray);
      zeichneTeilbaum(kind, zx, zy, Math.abs(dx) / 2, ebene + 1);
   }
}

/**
 * Selbsttest zu Höhe und ausgewogenem Einfügen. Bitte nicht verändern!
 * Starten: Klick auf das kleine Dreieck links neben "@Test"
 * (ganz oben: alle Tests) oder auf der Website "Tests starten".
 */
public class HoeheTest {

   private String name(BaumElement e) {
      if (e instanceof Knoten) {
         return ((Knoten) e).getDaten().gibSchluesselwert();
      }
      return "Abschluss";
   }

   private BaumElement links(BaumElement e) {
      if (e instanceof Knoten) {
         return ((Knoten) e).getLinks();
      }
      return e;
   }

   private BaumElement rechts(BaumElement e) {
      if (e instanceof Knoten) {
         return ((Knoten) e).getRechts();
      }
      return e;
   }

   private Binaerbaum elf() {
      Binaerbaum b = new Binaerbaum();
      b.einfuegen(new Spieler("Mika", 34));
      b.einfuegen(new Spieler("Emil", 12));
      b.einfuegen(new Spieler("Tara", 27));
      b.einfuegen(new Spieler("Bo", 8));
      b.einfuegen(new Spieler("Ines", 41));
      b.einfuegen(new Spieler("Pia", 19));
      b.einfuegen(new Spieler("Zoe", 3));
      b.einfuegen(new Spieler("Dana", 22));
      b.einfuegen(new Spieler("Kai", 15));
      b.einfuegen(new Spieler("Ruby", 50));
      b.einfuegen(new Spieler("Vik", 9));
      return b;
   }

   @Test
   public void hoeheLeer() {
      Assertions.assertEquals(0, new Binaerbaum().hoehe(), "Der leere Baum hat keine Ebene: Höhe 0. Was liefert der Abschluss?");
   }

   @Test
   public void hoeheEinKnoten() {
      Binaerbaum b = new Binaerbaum();
      b.einfuegenAlle("Mika");
      Assertions.assertEquals(1, b.hoehe(), "Ein einzelner Knoten bildet eine Ebene: Höhe 1.");
   }

   @Test
   public void hoeheElf() {
      Assertions.assertEquals(4, elf().hoehe(), "Das Verzeichnis aus 2.1 hat vier Ebenen.");
   }

   @Test
   public void hoeheEntartet() {
      Binaerbaum b = new Binaerbaum();
      b.einfuegenAlle("Ada Ben Cem Dio Eva");
      Assertions.assertEquals(5, b.hoehe(), "Sortiert eingefügt entsteht eine Kette: fünf Namen, fünf Ebenen.");
   }

   @Test
   public void hoeheSchief() {
      Binaerbaum b = new Binaerbaum();
      b.einfuegenAlle("Mika Bo Zoe Xia Wim");
      Assertions.assertEquals(4, b.hoehe(), "Der längste Ast zählt: Mika – Zoe – Xia – Wim.");
   }

   @Test
   public void ausgewogenSieben() {
      Binaerbaum b = new Binaerbaum();
      String[] namen = "Ada Ben Cem Dio Eva Fin Gil".split(" ");
      b.ausgewogenEinfuegen(namen, 0, 6);
      Assertions.assertEquals(7, b.anzahl(), "Alle sieben Namen müssen eingefügt werden.");
      Assertions.assertEquals(3, b.hoehe(), "Sieben Namen passen in drei Ebenen.");
      Assertions.assertEquals("Dio", name(b.getWurzel()), "Die Mitte (Dio) muss die Wurzel werden.");
   }

   @Test
   public void ausgewogenZehn() {
      Binaerbaum b = new Binaerbaum();
      String[] namen = "Ada Ben Cem Dio Eva Fin Gil Hal Ida Jo".split(" ");
      b.ausgewogenEinfuegen(namen, 0, 9);
      Assertions.assertEquals(10, b.anzahl(), "Alle zehn Namen müssen eingefügt werden.");
      Assertions.assertEquals(4, b.hoehe(), "Zehn Namen passen in vier Ebenen.");
   }
}
